#!/usr/bin/env bash
# run_cosim.sh - SCR1 through the OCV co-simulation: the program is loaded as stimulus, every
# committed instruction is compared with the RV32IMC reference model.
#
#   examples/scr1/run_cosim.sh <program.hex|.bin> [-- <cosim/runner options>]
#   examples/scr1/run_cosim.sh gen:random|gen:directed [-- ...]   programs generated by the model
#                                  (one per batch: add --batches N --reset-each-batch)
#
# Programs are SCR1 test images for the default memory map (e.g. hello.hex, built by
# scr1/sim/rvfi_coverif/co_verify.sh into scr1/build/verilator_AHB_*/). Extra Verilator defines
# for the core can be given in SCR1_DEFINES; SCR1_SRC points at another copy of scr1/src
# (fault injection).
set -euo pipefail
HERE=$(cd "$(dirname "$0")" && pwd)
OCV=$(cd "$HERE/../.." && pwd)
SCR1=$(cd "${SCR1:-$OCV/ext/scr1}" && pwd)
[ $# -ge 1 ] || { sed -n '2,9p' "$0"; exit 1; }
case $1 in
    gen:*) PROG_OPT="gen=${1#gen:}" ;;
    *)     PROG_OPT="program=$(realpath "$1")" ;;
esac
shift
[ "${1:-}" = "--" ] && shift

S=${SCR1_SRC:-$SCR1/src}
OUT=${OUT:-$HERE/build/cosim/scr1}
mkdir -p "$OUT"
{ sed -e '$a\' "$S/core.files"; sed -e '$a\' "$S/axi_top.files"
  printf '%s\n' core/cache/scr1_icache.sv core/cache/scr1_dcache.sv core/cache/scr1_cache_wrapper.sv; } \
  | sed "s#^#$S/#" > "$OUT/scr1_rtl.f"
mapfile -t RTL < "$OUT/scr1_rtl.f"

export RTL_DEFINES="-DSCR1_CFG_RV32IMC_MAX -DSCR1_RVFI_EN -I$S/includes ${SCR1_DEFINES:-}"
export MODEL_SRCS="$OCV/models/cpu/iss/rv32_iss.c $OCV/models/cpu/cpu_model.c $HERE/scr1_cov.c $HERE/scr1_gen.c ${CPU_SRCS:-}"
export MODEL_CFLAGS="-I$OCV/models/cpu/iss -I$OCV/models/cpu ${CPU_CFLAGS:-}"
export OUT
exec "$OCV/sim/cosim.sh" "$HERE/scr1.json" "$HERE/scr1_model.c" \
    "${RTL[@]}" "$HERE/scr1_ocv_axi_mem.sv" "$HERE/scr1_ocv_dut.sv" \
    -- --model-opt "$PROG_OPT" "$@"
